import com.kobil.kssidp.wrapper.models.*
import com.kobil.wrapper.events.AuthenticationMode

fun loginNative(idp: KssIdp, clientId: String, mode: AuthenticationMode,
    credentials: HashMap<String, String>, headers: HashMap<String, String>,
    completion: (KssIdpResultObject) -> Unit) {
    idp.login(clientId, mode, credentials, headers, null, completion)
}
// Use selected local user/deployment headers, never arbitrary first-user defaults.
// Handle failure/cancellation explicitly; do not reactivate on login failure.

ios.code:
import KSMasterController
import kssidp

func loginNative(idp: KssIdpWrapper, clientId: String, mode: KSMAuthenticationMode,
    credentials: [String: String], headers: [String: String],
    completion: @escaping KssIdpCompletion) {
    idp.login(clientId: clientId, authMode: mode, credentials: credentials,
        headers: headers, completion: completion)
}
// Headers bind the selected local user when required by the deployment.
// Verify authenticated SDK state in completion; never silently reactivate.
